 if(drawing.value&&!drag){if(store.busy)return;const p=drawingPoint(e);if(!p)return;if(drawingMove){const dx=p.xMm-drawingMove.xMm,dy=p.yMm-drawingMove.yMm,map=(n:{xMm:number;yMm:number})=>({xMm:n.xMm+dx,yMm:n.yMm+dy});applyDraftContour(mapShapeContour(draftContour(),map));drawingMove=p;}else if(drawingHandle>=0){const target=drawingHandleTarget(drawingHandle);if(target){if(target.ring===draftMarking.value&&draftCurves.value.length)applyDraftContour(moveContourNode(draftContour(),target.index,p));else target.ring[target.index]=p;}}else if(drawingStroke)appendDrawing(e);return;}
 if(moveSection(e))return;
 if(controlDrag>=0){const hit=surfaceHit(e);if(hit)curvePoints.value[controlDrag]={...curvePoints.value[controlDrag],...hit};return;}if(stroke){addCurvePoint(e);return;}
