function pickCanvas(event:MouseEvent){if(drawing.value||event.button!==0)return;if(attachedPointerSelection){attachedPointerSelection=false;return;}
 if(moved){moved=false;return;}const mesh=surface.value,matrix=screenMatrix(event.currentTarget);if(!mesh||!matrix)return;
 const point=new DOMPoint(event.clientX,event.clientY).matrixTransform(matrix.inverse()),points=new Map(mesh.vertices.map(v=>[v.id,projectPosition(v)])),bindings=new Map((store.data.project?.bindings??[]).flatMap(b=>b.report.faceIds.map(id=>[id,b.pieceId] as const)));let best:typeof projected.value[number]|null=null,bestDepth=-Infinity;
 for(const face of mesh.faces){const triangle=face.vertices.map(id=>points.get(id)!),weights=screenWeights(point,triangle);if(!weights)continue;const corrected=perspectiveWeights(weights,triangle.map(v=>v.inverseDepth)),depth=triangle.reduce((sum,v,i)=>sum+v.z*corrected[i],0);if(depth>bestDepth){bestDepth=depth;best={...face,pieceId:bindings.get(face.id),screen:triangle,points:'',depth,color:''};}}
