 const bindings=bindingByFace.value.get(face.id),mesh=surface.value,matrix=screenMatrix(event.currentTarget);if(!mesh||!matrix){clearPick();return;}
 const point=new DOMPoint(event.clientX,event.clientY).matrixTransform(matrix.inverse()),weights=screenWeights(point,face.screen);if(!weights)return;const corrected=perspectiveWeights(weights.map(w=>Math.max(0,w)) as [number,number,number],face.screen.map(v=>v.inverseDepth));
