async function lockBoundary(){const p=store.data.project,mesh=surface.value;if(!p||!mesh)return;const selected=new Set(selectedFaces.value),edges=new Map<string,{a:string;b:string;inside:number;total:number}>();for(const face of mesh.faces)face.vertices.forEach((a,i)=>{const b=face.vertices[(i+1)%3],key=[a,b].sort().join(':'),e=edges.get(key)??{a,b,inside:0,total:0};e.total++;if(selected.has(face.id))e.inside++;edges.set(key,e);});const added=[...edges.values()].filter(e=>e.inside===1&&e.total===2).map(e=>({a:e.a,b:e.b,locked:true})),constraints=new Map((mesh.cutConstraints??[]).map(c=>[[c.a,c.b].sort().join(':'),c]));for(const c of added)constraints.set([c.a,c.b].sort().join(':'),c);await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'surface.set',surface:{...JSON.parse(JSON.stringify(mesh)),cutConstraints:[...constraints.values()]}}));}
