<template><div class="surface-panel"><div class="surface-preview" @dragover="dragOverSource" @drop="dropSource"> <template v-if="surface"><div class="surface-summary">{{modelSourceLabel(surface.source,zh)}} · {{surface.vertices.length}} {{zh?'顶点':localize('vertices')}} / {{surface.faces.length}} {{zh?'面':localize('faces')}} · {{zh?'拓扑版本':localize('topology')}} {{surface.topologyVersion}}<label v-show="(mode==='cutting')"><input v-model="regionMode" type="checkbox">{{zh?'分区选择模式':localize('Region selection mode')}}</label><template v-if="regionMode"><input v-model="regionName" maxlength="80"><button :disabled="!selectedFaces.length||store.busy" @click="assignRegion">{{zh?'将选中面分为新片区':localize('Assign selected faces to region')}} · {{selectedFaces.length}}</button><button :disabled="!selectedFaces.length||store.busy" @click="lockBoundary">{{zh?'锁定选中区域边界为切缝':localize('Lock selected boundary as cuts')}}</button><button :disabled="!surface.cutConstraints?.length||store.busy" @click="clearCuts">{{zh?'清除锁定切缝':localize('Clear locked cuts')}} · {{surface.cutConstraints?.length??0}}</button><button @click="selectedFaces=[]">{{zh?'清空选择':localize('Clear selection')}}</button></template></div>
  <div v-if="surface.faces.length>5000" class="lod-status">{{zh?'显示':localize('Display')}} {{displayMesh?.faces.length}} / {{surface.faces.length}} {{zh?'面 · 几何近似误差上界':localize('faces · displacement bound')}} {{(displayMesh?.errorMm??0).toFixed(2)}} mm <label><input v-model="detail" type="checkbox">{{zh?'完整网格':localize('Full mesh')}}</label><span>{{zh?'点击精确拾取原始模型。':localize('Picking uses the exact original mesh; region, distortion and marking views use full detail.')}}</span></div><div v-if="heatmap" class="distortion-legend"><select v-model="metric" aria-label="Distortion metric"><option value="distortion">D</option><option value="areaError">EA</option><option value="edgeError">EE</option><option value="angleError">Eθ / π</option></select><span>0</span><i></i><span>{{distortionScales[metric]}}+</span><small>{{zh?'绿→黄→红；灰色 = 无数据。Eθ 的 0.05 为显示刻度。':localize('Green → yellow → red; grey = unavailable. Eθ 0.05 is a display scale.')}}</small></div><div v-if="pendingPick" class="binding-choices"><strong>{{zh?'此面对应多张裁片，请选择：':localize('This face maps to multiple pieces. Choose:')}}</strong><button v-for="id in pendingPick.pieceIds" :key="id" @click="choosePiece(id)">{{store.data.project?.pieces.find(p=>p.id===id)?.name}} / {{id.slice(0,8)}}</button><button @click="clearPick">{{zh?'取消选择':localize('Cancel selection')}}</button></div><div v-if="mode==='cutting'" class="drawing-parts"><details><summary>{{zh?'绘制部件：已选':localize('Drawing parts: selected')}} {{curveRegions.length}} / {{drawingRegions.length}}</summary><button @click="curveRegions=[...drawingRegions]">{{zh?'全选部件':localize('Select all parts')}}</button><button @click="curveRegions=[]">{{zh?'清空部件':localize('Clear parts')}}</button><label v-for="region in drawingRegions" :key="region"><input v-model="curveRegions" type="checkbox" :value="region">{{region}}</label></details></div><nav class="surface-tool-rail" :aria-label="zh?'三维视图工具':localize('3D view tools')">
